using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Train the model at startup and log evaluation metrics
var trainingService = new ModelTrainingService(
    LoggerFactory.Create(b => b.AddConsole()).CreateLogger<ModelTrainingService>());
trainingService.TrainAndEvaluate();

// Register the pooled prediction engine (thread-safe) and label mapping
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainingService.ModelPath);
builder.Services.AddSingleton<ILabelService>(new LabelService(trainingService.ModelPath));

var app = builder.Build();
app.MapControllers();
app.Run();

